-- les entités de Johto déjà présentes ne sont modifiées que si elles n’ont pas été retouchées.
UPDATE "zones" SET "description" = 'Le chemin herbeux qui relie Bourg Geon à Ville Griotte. Idéal pour débuter.', "encounters" = '[{"speciesId":161,"weight":30,"minLevel":2,"maxLevel":4},{"speciesId":163,"weight":25,"minLevel":2,"maxLevel":4},{"speciesId":187,"weight":15,"minLevel":3,"maxLevel":5},{"speciesId":16,"weight":15,"minLevel":2,"maxLevel":4},{"speciesId":19,"weight":15,"minLevel":2,"maxLevel":4}]'::jsonb
WHERE "id" = 'route-29' AND "id" IS NOT DISTINCT FROM 'route-29' AND "region_id" IS NOT DISTINCT FROM 'johto' AND "order" IS NOT DISTINCT FROM 0 AND "name" IS NOT DISTINCT FROM 'Route 29' AND "description" IS NOT DISTINCT FROM 'Le chemin herbeux qui relie Bourg Geon à Ville Griotte.' AND "image" IS NOT DISTINCT FROM NULL AND "habitat" IS NOT DISTINCT FROM 'grassland' AND "min_power" IS NOT DISTINCT FROM 0 AND "enabled" IS NOT DISTINCT FROM true AND "required_types" IS NOT DISTINCT FROM '[]'::jsonb AND "affinity_types" IS NOT DISTINCT FROM '["normal","flying"]'::jsonb AND "durations_minutes" IS NOT DISTINCT FROM '[2,5,15,60,240,480]'::jsonb AND "encounters" IS NOT DISTINCT FROM '[{"speciesId":161,"weight":30,"minLevel":3,"maxLevel":6},{"speciesId":163,"weight":25,"minLevel":3,"maxLevel":6},{"speciesId":165,"weight":15,"minLevel":4,"maxLevel":6},{"speciesId":187,"weight":15,"minLevel":4,"maxLevel":6},{"speciesId":167,"weight":15,"minLevel":4,"maxLevel":6}]'::jsonb AND "loot_table_id" IS NOT DISTINCT FROM 'butin-route' AND "unlock" IS NOT DISTINCT FROM '{"type":"always"}'::jsonb;--> statement-breakpoint
