UPDATE "quests" SET "unlock" = regexp_replace("unlock"::text, '"type": "badgeCount", "count": ([0-9]+)}', '"type": "badgeCount", "count": \1, "regionId": "kanto"}', 'g')::jsonb WHERE "region_id" = 'kanto' AND "unlock"::text ~ '"type": "badgeCount", "count": [0-9]+}';--> statement-breakpoint
